#include "audio/AudioEngine.h"
#include <algorithm>
#include <cmath>
namespace jeff::daw {void AudioEngine::prepare(double r,int,int)noexcept{rate=r>0?r:48000;clock.prepare(rate);phase=0;}void AudioEngine::setAuditionNote(int n,float v)noexcept{delta=2*3.14159265358979323846*440.0*std::pow(2.0,(n-69)/12.0)/rate;level=std::clamp(v,0.0f,1.0f)*.25f;active=true;}void AudioEngine::processBlock(float*const*ch,int nc,int ns)noexcept{if(!ch||nc<=0||ns<=0)return;for(int c=0;c<nc;++c)if(ch[c])std::fill_n(ch[c],ns,0.0f);auto tb=clock.process(ns);float peak=0;for(int i=0;i<ns;++i){float s=active?std::sin(phase)*level:0;phase+=delta;if(phase>6.283185307)phase-=6.283185307;for(int k=0;k<tb.clickCount;++k)if(i>=tb.clickOffsets[k]&&i<tb.clickOffsets[k]+64)s+=.12f*(1-(i-tb.clickOffsets[k])/64.0f);s=std::clamp(s,-1.0f,1.0f);peak=std::max(peak,std::abs(s));for(int c=0;c<nc;++c)if(ch[c])ch[c][i]=s;}outPeak.store(peak);}}
